[
  {
    "statement": "The most effective ways to manage uncropped field margins on European farmland to support bumblebees include several approaches based on evidence from European trials.",
    "citations": []
  },
  {
    "statement": "Sowing uncropped arable field margins with an agricultural nectar and pollen seed mix has been documented to support foraging bumblebees.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "Field margins sown with perennial leguminous flowering plants attract significantly more foraging bumblebees than naturally regenerated, grassy, or cropped field margins.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "Agricultural forage plant mixes that include legumes attract greater numbers of bumblebees than perennial wildflower mixes, at least in the first year.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "Margins sown with agricultural legume plants degrade in their value to bumblebees and would need re-sowing every few years.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "Sowing uncropped field margins with a native wild flower seed mix is an effective method for supporting bumblebees.",
    "citations": [
      "19"
    ]
  },
  {
    "statement": "Uncropped field margins sown with a native wild flower seed mix support a higher abundance and species richness of foraging bumblebees than cropped field edges, grassy margins, or naturally regenerated uncropped margins.",
    "citations": [
      "19"
    ]
  },
  {
    "statement": "Perennial leguminous herbs in seed mixtures are particularly important forage sources for bumblebees, especially long-tongued species.",
    "citations": [
      "19"
    ]
  },
  {
    "statement": "Leaving arable field margins uncropped to allow for natural regeneration has shown benefits for bumblebees.",
    "citations": [
      "20"
    ]
  },
  {
    "statement": "More bumblebees and bee species forage on naturally regenerated uncropped field margins than on cropped margins.",
    "citations": [
      "20"
    ]
  },
  {
    "statement": "The value of naturally regenerated uncropped field margins is not consistent from year to year.",
    "citations": [
      "20"
    ]
  },
  {
    "statement": "The value of naturally regenerated uncropped field margins is often based on thistle species, which are considered pernicious weeds.",
    "citations": [
      "20"
    ]
  },
  {
    "statement": "Increasing areas of rough grassland provides important nesting sites for bumblebees.",
    "citations": [
      "12"
    ]
  },
  {
    "statement": "Grassy field margins attracted nest-searching queen bumblebees at higher densities than cropped field margins.",
    "citations": [
      "12"
    ]
  },
  {
    "statement": "Providing grass strips at field margins shows mixed results for supporting bumblebee populations.",
    "citations": [
      "14"
    ]
  },
  {
    "statement": "Some trials showed that grass strips at field margins enhanced the abundance and diversity of bumblebees, while others showed no effect.",
    "citations": [
      "14"
    ]
  },
  {
    "statement": "European agri-environment schemes have shown variable results for enhancing wild bee populations.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "Some trials of European agri-environment schemes showed enhanced diversity and abundance of wild bees, while other trials found no enhancement.",
    "citations": [
      "24"
    ]
  }
]

[
  {
    "statement": "Different management approaches for uncropped arable field margins in Europe show varying benefits for bumblebees based on replicated trials.",
    "citations": []
  },
  {
    "statement": "Five replicated trials in Europe documented bumblebees foraging on field margins sown with agricultural nectar and pollen seed mixes.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "Field margins sown with perennial leguminous flowering plants attract significantly more foraging bumblebees than naturally regenerated margins, according to four replicated trials.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "In the UK, three out of five replicated trials showed that uncropped field margins sown with wild flowers and subsequently mown support a higher abundance and species richness of foraging bumblebees than naturally regenerated uncropped margins.",
    "citations": [
      "19"
    ]
  },
  {
    "statement": "One small trial recorded the same number of bee species on wildflower sown strips and on naturally regenerated strips.",
    "citations": [
      "19"
    ]
  },
  {
    "statement": "Three replicated trials showed that a mix of agricultural forage plants including legumes attracts greater numbers of bumblebees than a perennial wildflower mix, at least in the first year.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "Two trials demonstrated that perennial leguminous herbs in wildflower seed mixtures are important forage sources for bumblebees.",
    "citations": [
      "19"
    ]
  },
  {
    "statement": "Perennial leguminous herbs in wildflower seed mixtures are particularly important forage sources for long-tongued bumblebee species.",
    "citations": [
      "19"
    ]
  },
  {
    "statement": "Three trials in the UK found evidence that margins sown with agricultural legume plants degrade in their value to bumblebees over time.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "Margins sown with agricultural legume plants would need to be re-sown every few years to maintain their value to bumblebees.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "Four replicated trials in the UK found more bumblebees foraging on naturally regenerated uncropped field margins than on cropped margins.",
    "citations": [
      "20"
    ]
  },
  {
    "statement": "Two trials note that the value of naturally regenerated uncropped field margins for bumblebees is based on thistle species.",
    "citations": [
      "20"
    ]
  },
  {
    "statement": "The thistle species providing value on naturally regenerated uncropped field margins are considered pernicious weeds that require control.",
    "citations": [
      "20"
    ]
  },
  {
    "statement": "Two trials found that the value of naturally regenerated uncropped field margins for bees was not consistent from year to year.",
    "citations": [
      "20"
    ]
  }
]

[
  {
    "statement": "Based on trials in Europe and North America, phacelia (Phacelia tanacetifolia) shows variable effectiveness as a floral resource for wild bees depending on location.",
    "citations": []
  },
  {
    "statement": "Ten trials monitored bees foraging on farmland patches sown with a high proportion of phacelia.",
    "citations": []
  },
  {
    "statement": "All but one of the ten trials found substantial numbers of foraging wild (non-Apis) bees.",
    "citations": []
  },
  {
    "statement": "The wild bees found foraging on the phacelia patches were particularly bumblebees.",
    "citations": []
  },
  {
    "statement": "Six of the trials recorded the number of foraging bee species, which ranged from eight to 35.",
    "citations": []
  },
  {
    "statement": "One replicated trial shows that phacelia is not very attractive to wild bees in Greece.",
    "citations": []
  },
  {
    "statement": "The lack of attractiveness of phacelia in Greece demonstrates a clear geographical variation in the plant's effectiveness.",
    "citations": []
  },
  {
    "statement": "Evidence indicates that phacelia generally attracts substantial numbers of wild bees across most European and North American locations studied.",
    "citations": []
  },
  {
    "statement": "The attractiveness of phacelia to wild bees varies significantly by region.",
    "citations": []
  },
  {
    "statement": "Phacelia's performance as a floral resource for wild bees was documented as notably poor in Greece compared to other locations.",
    "citations": []
  }
]

[
  {
    "statement": "The documented benefits of controlling or excluding competitor or predator species from bee nesting sites include increased offspring production.",
    "citations": []
  },
  {
    "statement": "A replicated controlled trial showed that excluding ants from solitary nests of the endemic Australian bee Exonuera nigrescens increased production of offspring.",
    "citations": [
      "46"
    ]
  },
  {
    "statement": "Studies on artificial nest sites show that proper nest design can reduce parasitism and mortality.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "Nest boxes with plastic-lined holes, plastic or paper tubes are much less productive due to parasitism or mould compared to reed stem and wooden grooved-board nest boxes.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "Mortality rates from parasites and predators in bee nest boxes range from 13% mortality for cavity-nesting bees in Germany to 56% mortality overall for subtropical carpenter bees in India.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "Predators and competitors can have a significant impact on bee reproductive success.",
    "citations": [
      "47"
    ]
  }
]

[
  {
    "statement": "Several effective actions can be taken to support wild bee populations in urban areas and along infrastructure corridors.",
    "citations": []
  },
  {
    "statement": "Stopping the use of herbicides on pavements and road verges has proven beneficial.",
    "citations": [
      "3899"
    ]
  },
  {
    "statement": "Restored roadside prairies where herbicide application was restricted showed greater species richness and abundance of butterflies than verges dominated by non-native weeds with unrestricted herbicide use.",
    "citations": [
      "3899"
    ]
  },
  {
    "statement": "Managing land under power lines for wildlife provides habitat for bees.",
    "citations": [
      "31"
    ]
  },
  {
    "statement": "One study found more bee species under power lines managed as scrub than in annually mown grassland.",
    "citations": [
      "31"
    ]
  },
  {
    "statement": "Altering mowing regimes on greenspaces and road verges significantly benefits pollinators.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Less frequently mown or unmown urban greenspaces showed higher species richness and diversity of butterflies and moths than more frequently mown areas.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Roads and verges managed by mowing once or twice a year, or not at all, had a similar abundance of butterflies to remnant prairies.",
    "citations": [
      "3854"
    ]
  },
  {
    "statement": "Restoring or maintaining species-rich grassland along road and railway verges is highly effective.",
    "citations": [
      "3854"
    ]
  },
  {
    "statement": "Restored roadside prairies and verges sown with native wildflowers showed higher species richness and diversity of butterflies, day-flying moths, burnet moths, and meadow-specialist moths than verges dominated by non-native vegetation.",
    "citations": [
      "3854"
    ]
  },
  {
    "statement": "Verges with more butterfly species' larval food plants and more plant species in flower had a greater abundance of butterflies and burnet moths.",
    "citations": []
  },
  {
    "statement": "Providing nest boxes for solitary bees is a practical urban solution.",
    "citations": [
      "80"
    ]
  },
  {
    "statement": "Nest boxes were readily used by bees.",
    "citations": [
      "80"
    ]
  },
  {
    "statement": "Repeated provision of nest boxes almost doubled the number of occupied solitary bee nests over three years.",
    "citations": [
      "80"
    ]
  },
  {
    "statement": "Occupancy rates for nest boxes ranged from 1% to 26% of available cavities.",
    "citations": []
  },
  {
    "statement": "The occupied nest boxes supported between 4.6 and 33 bee species.",
    "citations": []
  },
  {
    "statement": "Planting nectar flower mixtures and wildflower strips enhances urban pollinator habitat.",
    "citations": [
      "442"
    ]
  },
  {
    "statement": "In a review of sixty-five studies on the effects of flower planting on invertebrates, fifty of those studies showed positive results.",
    "citations": [
      "442"
    ]
  },
  {
    "statement": "Sown wildflower strips consistently showed higher species richness and diversity of butterflies and moths than conventional field margins, unsown margins, or cropped fields.",
    "citations": [
      "3932"
    ]
  },
  {
    "statement": "Sown wildflower strips supported a higher abundance of both generalist and specialist butterflies.",
    "citations": [
      "3932"
    ]
  }
]

[
  {
    "statement": "Captive rearing of bumblebee colonies has been attempted using various methods.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "Methods for rearing bumblebees in captivity include confining mated queens alone, with bumblebee workers, with honey bee workers, or with male bumblebee pupae.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "Another method for rearing bumblebees in captivity involves anaesthetisation with CO2.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "The success rates of captive bumblebee rearing vary significantly by species.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "Some declining North American bumblebee species show particular challenges in captive rearing.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "Queens of the half-black bumblebee B. vagans successfully reared adults in captivity.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "Queens of the yellow-banded bumblebee B. terricola successfully reared adults in captivity.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "The yellow bumblebee B. fervidus consistently failed in captive rearing attempts, as queens laid eggs but larvae died before becoming adults.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "The rusty-patched bumblebee and the American bumblebee B. pensylvanicus showed similar rearing failures where larvae died before becoming adults.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "Over four years of artificial rearing, Bombus terrestris queens gradually decreased in weight.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "Diet composition significantly influences the reproductive success of bumblebees.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "Buff-tailed bumblebee B. terrestris colonies fed freshly frozen pollen produce larger queens with better survival and larger colonies compared to those fed dried, frozen pollen.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "Buff-tailed bumblebee workers produce more offspring when fed pollen with a higher protein content.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "Artificial light regimes of eight hours of light and 16 hours of darkness can reduce egg-laying time in artificially reared queen B. terrestris compared to constant darkness.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "Queens hibernated at 4-5°C for 45 days had enhanced egg-laying and colony formation rates.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "Queens hibernated at 4-5°C for 45 days produced smaller colonies than non-hibernated queens.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "For good survival, bumblebee queens should weigh more than 0.6g and be hibernated for four months or less.",
    "citations": [
      "50"
    ]
  },
  {
    "statement": "Reintroduction of laboratory-reared bumblebee colonies into the environment has had variable success.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "In two UK reintroduction trials, the numbers of new queens produced per colony were very low or zero.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Two other reintroduction trials produced good numbers of new queens.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Social parasitism by cuckoo bees presents a significant challenge to reintroduced bumblebee colonies.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Parasitism rates by cuckoo bees on reintroduced colonies varied widely across trials, from 0% to 79%.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Parasitism by cuckoo bees was reduced by placing colonies in landscapes with intermediate nectar and pollen availability.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Parasitism by cuckoo bees was reduced by releasing colonies later in the season.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "The effects of supplementary feeding on reintroduced bumblebee colonies are inconsistent.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "One Canadian trial showed supplementary feeding improved reproductive success but did not reduce the parasite load.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "A USA trial found that supplementary feeding did not increase colony productivity.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Translocation trials from the 1950s-1960s showed evidence of queen death and lower colony productivity in moved bumblebee colonies.",
    "citations": [
      "53"
    ]
  },
  {
    "statement": "Only early bumblebee Bombus pratorum colonies adapted well to being moved during translocation trials.",
    "citations": [
      "53"
    ]
  }
]

[
  {
    "statement": "Several risks and control methods are associated with using commercial bee colonies for pollination.",
    "citations": []
  },
  {
    "statement": "Commercial bee colonies face risks from multiple pathogens.",
    "citations": []
  },
  {
    "statement": "Nosema bombi infections can occur in managed western bumblebee colonies.",
    "citations": [
      "42"
    ]
  },
  {
    "statement": "The antibiotic fumagillin was not effective against Nosema bombi infection in trials.",
    "citations": [
      "42"
    ]
  },
  {
    "statement": "Indian meal moth infestations in commercial bumblebee colonies can be controlled using the insect pathogen Bacillus thuringiensis at a strength of 1 gram per litre of water.",
    "citations": []
  },
  {
    "statement": "The spread of small hive beetles through commercial honey bee transport packages is problematic.",
    "citations": [
      "41"
    ]
  },
  {
    "statement": "In trials, more than half of the small hive beetles escaped from transport packages.",
    "citations": [
      "41"
    ]
  },
  {
    "statement": "Mite-killing strips did not kill the small hive beetles in trials.",
    "citations": [
      "41"
    ]
  },
  {
    "statement": "Parasites and pathogens can be problematic for commercially managed solitary bee species in the family Megachilidae.",
    "citations": [
      "54"
    ]
  },
  {
    "statement": "Specific control methods have been developed for parasites and pathogens in commercially managed solitary bee species.",
    "citations": [
      "54"
    ]
  },
  {
    "statement": "Mortality rates ranged from 2% to 56% overall in managed solitary bee populations due to parasitism and other factors.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "Mortality rates in managed solitary bee populations varied significantly by location and species.",
    "citations": [
      "47"
    ]
  },
  {
    "statement": "Laboratory-reared bumblebee colonies released to the wild experienced variable rates of social parasitism by cuckoo bees.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Social parasitism rates by cuckoo bees in released bumblebee colonies ranged from 0% in some trials to 79% in others.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Parasitism rates were reduced by placing bumblebee colonies in landscapes with intermediate rather than very high nectar and pollen availability.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Parasitism rates were reduced by releasing bumblebee colonies late rather than early in the season.",
    "citations": [
      "52"
    ]
  },
  {
    "statement": "Local solitary bee populations can increase up to six-fold in one year under management when good conditions and plentiful floral resources are provided.",
    "citations": [
      "54"
    ]
  },
  {
    "statement": "High larval mortality was found when rearing bees on artificial diets, including diets with honey bee-collected pollen.",
    "citations": [
      "54"
    ]
  }
]

[
  {
    "statement": "There are limited studies comparing the management of hedges for bees in Scotland to the management of land under power lines for bees in the USA.",
    "citations": []
  },
  {
    "statement": "A replicated controlled trial showed that hedges in Scotland managed under the Scottish Rural Stewardship scheme do not attract more nest-searching or foraging queen bumblebees in spring than conventionally managed hedgerows.",
    "citations": [
      "15"
    ]
  },
  {
    "statement": "Studies on general hedge management found mixed results.",
    "citations": [
      "116"
    ]
  },
  {
    "statement": "Five studies from the UK found that hedge management did not affect numbers of bumblebee queens.",
    "citations": [
      "116"
    ]
  },
  {
    "statement": "A replicated trial in Maryland, USA, found more bee species under power lines managed as scrub than in equivalent areas of annually mown grassland.",
    "citations": [
      "31"
    ]
  },
  {
    "statement": "There is currently no captured evidence for the effects of managing land under power lines specifically to benefit wildlife on farmland.",
    "citations": [
      "99"
    ]
  },
  {
    "statement": "Related studies on butterflies and moths under power lines show positive management effects in multiple countries, including the USA.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "Positive management findings for butterfly and moth populations under power lines cannot be directly extrapolated to bee populations.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "The limited evidence suggests that power line corridor management in the USA may show more promise for bee conservation than hedge management approaches tested in Scotland.",
    "citations": []
  },
  {
    "statement": "More research is needed for definitive comparisons between the effectiveness of power line corridor management in the USA and hedge management in Scotland for bee conservation.",
    "citations": []
  }
]

[
  {
    "statement": "The evidence on bee translocation and population augmentation for genetic diversity improvement is extremely limited.",
    "citations": []
  },
  {
    "statement": "One trial in Brazil showed that genetic diversity can be maintained in small isolated populations of stingless bees Melipona scutellaris by regularly introducing inseminated queens.",
    "citations": [
      "56"
    ]
  },
  {
    "statement": "One replicated trial in India demonstrated that translocating carpenter bees Xylocopa fenestrata in immature stages can establish a population at a new site.",
    "citations": [
      "55"
    ]
  },
  {
    "statement": "If adult carpenter bees Xylocopa fenestrata are translocated, a very small proportion remain at the new site.",
    "citations": [
      "55"
    ]
  },
  {
    "statement": "No studies were found for butterflies and moths that evaluated the effects of introducing mated females to increase genetic diversity.",
    "citations": [
      "3912"
    ]
  },
  {
    "statement": "One study in the Czech Republic found that 69 years after translocation, an introduced population of the small mountain ringlet butterfly had similar genetic diversity to the butterfly's source population.",
    "citations": [
      "3911"
    ]
  },
  {
    "statement": "The introduced population of the small mountain ringlet butterfly also had higher genetic diversity than a small native population.",
    "citations": [
      "3911"
    ]
  },
  {
    "statement": "No studies were found on the effects of ensuring genetic variation in translocated birds.",
    "citations": [
      "583"
    ]
  },
  {
    "statement": "The overall evidence base for bee translocation and genetic augmentation strategies remains very sparse.",
    "citations": []
  },
  {
    "statement": "Only isolated examples of success for bee translocation and genetic augmentation strategies have been documented.",
    "citations": []
  }
]

